WITH wk AS (SELECT (current_date - extract(dow FROM current_date)::int) AS sunday), cleared AS (DELETE FROM slots RETURNING 1), src(team_name, d, e, start_time, type, note) AS (VALUES (U&'\05E0\05D5\05E2\05E8', 0, NULL, '09:00', 'vasermil_1', NULL), (U&'\05E0\05D5\05E2\05E8', 0, NULL, '19:30', 'vasermil_1', NULL), (U&'\05E0\05D5\05E2\05E8', 1, NULL, '19:30', 'vasermil_1', NULL), (U&'\05E0\05D5\05E2\05E8', 3, NULL, '19:30', 'vasermil_2', NULL), (U&'\05E0\05D5\05E2\05E8', 6, NULL, '20:00', 'home_game', U&'\05DC\05D9\05D2\05D4'), (U&'\05E0\05E2\05E8\05D9\05DD \05D0', 0, NULL, '18:00', 'vasermil_2', NULL), (U&'\05E0\05E2\05E8\05D9\05DD \05D0', 2, NULL, '18:00', 'vasermil_2', NULL), (U&'\05E0\05E2\05E8\05D9\05DD \05D0', 4, NULL, '18:00', 'vasermil_1', NULL), (U&'\05E0\05E2\05E8\05D9\05DD \05D0', 6, NULL, '11:00', 'away_game', NULL), (U&'\05E0\05E2\05E8\05D9\05DD \05D1', 0, NULL, '16:30', 'vasermil_3', NULL), (U&'\05E0\05E2\05E8\05D9\05DD \05D1', 2, NULL, '16:30', 'vasermil_3', NULL), (U&'\05E0\05E2\05E8\05D9\05DD \05D1', 4, NULL, '16:30', 'vasermil_3', NULL), (U&'\05E0\05E2\05E8\05D9\05DD \05D2', 1, NULL, '17:00', 'vasermil_4', NULL), (U&'\05E0\05E2\05E8\05D9\05DD \05D2', 3, NULL, '17:00', 'vasermil_4', NULL), (U&'\05E0\05E2\05E8\05D9\05DD \05D2', 5, NULL, NULL, 'off', U&'\05D7\05D5\05E4\05E9'), (U&'\05D9\05DC\05D3\05D9\05DD \05D0', 0, NULL, '17:00', 'vasermil_1', NULL), (U&'\05D9\05DC\05D3\05D9\05DD \05D0', 2, NULL, '17:00', 'vasermil_1', NULL), (U&'\05D9\05DC\05D3\05D9\05DD \05D0', 4, NULL, '17:00', 'vasermil_2', NULL), (U&'\05D9\05DC\05D3\05D9\05DD \05D1', 1, NULL, '16:00', 'vasermil_2', NULL), (U&'\05D9\05DC\05D3\05D9\05DD \05D1', 3, NULL, '16:00', 'vasermil_2', NULL), (U&'\05D9\05DC\05D3\05D9\05DD \05D1 \05DC', 1, NULL, '16:00', 'vasermil_3', NULL), (U&'\05D9\05DC\05D3\05D9\05DD \05D1 \05DC', 4, NULL, '16:00', 'vasermil_3', NULL), (U&'\05D9\05DC\05D3\05D9\05DD \05D2', 0, NULL, '17:30', 'vasermil_4', NULL), (U&'\05D9\05DC\05D3\05D9\05DD \05D2', 3, NULL, '17:30', 'vasermil_4', NULL), (U&'\05D9\05DC\05D3\05D9\05DD \05D2 \05DC', 2, NULL, '15:30', 'vasermil_1', NULL), (U&'\05D9\05DC\05D3\05D9\05DD \05D2 \05DC', 4, NULL, '15:30', 'vasermil_1', NULL), (U&'\05D8\05E8\05D5\05DD \05D0', 0, NULL, '17:00', 'vasermil_3', U&'\05D4\05EA\05E8\05E9\05DE\05D5\05EA'), (U&'\05D8\05E8\05D5\05DD \05D0', 2, NULL, '17:00', 'vasermil_3', NULL), (U&'\05D8\05E8\05D5\05DD \05D0 \05DC', 1, NULL, '16:30', 'vasermil_4', NULL), (U&'\05D8\05E8\05D5\05DD \05D0 \05DC', 4, NULL, '16:30', 'vasermil_4', NULL), (U&'\05D8\05E8\05D5\05DD \05D1', 0, NULL, '16:00', 'vasermil_1', NULL), (U&'\05D8\05E8\05D5\05DD \05D1', 3, NULL, '16:00', 'vasermil_1', NULL), (U&'\05D8\05E8\05D5\05DD \05D1 \05DC', 2, NULL, '15:00', 'vasermil_2', NULL), (U&'\05D8\05E8\05D5\05DD \05D1 \05DC', 4, NULL, '15:00', 'vasermil_2', NULL), (U&'\05D8\05E8\05D5\05DD \05D2', 1, 3, NULL, 'camp', U&'\05DE\05D7\05E0\05D4 \05D0\05D9\05DE\05D5\05DF'), (U&'\05D1\05D9\05EA \05E1\05E4\05E8', 5, NULL, '09:00', 'other', U&'\05D0\05D9\05DE\05D5\05DF \05D1\05D9\05EA \05E1\05E4\05E8'), (U&'\05DE.\05E7\05D9\05D9\05E5', 0, NULL, NULL, 'off', U&'\05E1\05D9\05D5\05DD \05DE\05D7\05E0\05D4'), (U&'\05D4\05E2\05E8\05D5\05EA', 6, NULL, NULL, 'other', U&'\05DE\05E9\05D7\05E7\05D9 \05D1\05D9\05EA \05D1\05E9\05D1\05EA \2014 \05DC\05D4\05D2\05D9\05E2 \05E9\05E2\05D4 \05DC\05E4\05E0\05D9. \05E2\05D3\05DB\05D5\05DF \05D0\05D7\05E8\05D5\05DF \05D1\05D0\05EA\05E8.') ) INSERT INTO slots (team_id, date, end_date, start_time, type, note) SELECT t.id, to_char(wk.sunday + src.d, 'YYYY-MM-DD'), CASE WHEN src.e IS NULL THEN NULL ELSE to_char(wk.sunday + src.e, 'YYYY-MM-DD') END, src.start_time, src.type, src.note FROM src JOIN teams t ON t.name = src.team_name CROSS JOIN wk WHERE (SELECT count(*) FROM cleared) >= 0;
